function drawMap(){const c=mapCtx,w=180,scale=w/WORLD;c.fillStyle='#466759';c.fillRect(0,0,w,w);for(const b of BLOCKS){c.fillStyle=DISTRICTS[b.district].color;c.fillRect((b.x-9+WORLD/2)*scale,(b.z-9+WORLD/2)*scale,18*scale,18*scale)}c.strokeStyle='#739491';c.lineWidth=4;for(let i=-3;i<=3;i++){const n=(i*24+WORLD/2)*scale;c.beginPath();c.moveTo(n,0);c.lineTo(n,w);c.moveTo(0,n);c.lineTo(w,n);c.stroke()}for(const o of game.objects){if(o.owner||o.cooldown>0)continue;c.fillStyle=o.size<game.player.r/1.1?'#d9e9b9':'#82a19a';c.fillRect((o.px+WORLD/2)*scale,(o.pz+WORLD/2)*scale,o.size>3?3:1.5,o.size>3?3:1.5)}for(const h of [...game.holes.slice(1),game.player]){if(h.respawn>0)continue;const x=(h.x+WORLD/2)*scale,z=(h.z+WORLD/2)*scale;c.fillStyle=h.color;c.beginPath();c.arc(x,z,Math.max(3,h.r*scale),0,Math.PI*2);c.fill();if(!h.id){c.strokeStyle='white';c.lineWidth=2;c.stroke()}}}
